function StartDeathTimer(seconds) {
    // seconds å¿…é¡»æ˜?>= 1 çš„æ•´æ•°ï¼Œå¦åˆ™ç›´æŽ¥ä¸å¯åŠ?
    const s = Math.max(0, Math.floor(seconds));
    g_DeathRemain = s;

    const row = $("#DeathRow");
    if (row) row.RemoveClass("Hidden");

    // ç«‹å³åˆ·æ–°ä¸€æ¬¡æ–‡æœ?
    const label = $("#DeathTimerLabel");
    if (label) label.text = $.Localize("#Revive") + g_DeathRemain + "s";

    // ç¡®ä¿åªæœ‰ä¸€æ¡å¾ªçŽ¯åœ¨è·?
    if (!g_DeathTicking) {
        g_DeathTicking = true;
        TickDeathTimer();
    }
}

function TickDeathTimer() {
    // å¾ªçŽ¯å”¯ä¸€å‡ºå£ï¼šä¸æ¿€æ´»å°±åœæ­¢å¹¶é‡Šæ”?ticking é”?
    if (!g_DeathActive) {
        g_DeathTicking = false;
        return;
    }

    // æ¯ç§’é€’å‡ä¸€æ¬?
    g_DeathRemain -= 1;

    if (g_DeathRemain <= 0) {
        const row = $("#DeathRow");
        if (row) row.AddClass("Hidden");
        g_DeathActive = false;
        g_DeathTicking = false;
        return;
    }

    const label = $("#DeathTimerLabel");
    if (label) label.text = $.Localize("#Revive") + g_DeathRemain + "s";

    $.Schedule(1.0, TickDeathTimer);
}


function OnHeroFakeDeath(event) {
    
    const localHero = Players.GetPlayerHeroEntityIndex(Players.GetLocalPlayer());

    if (event.entindex !== localHero)
        return;

    const row = $("#DeathRow");
    if (!row) return;

    if (event.is_dead === 1) {
        const dur = 10;
        const seconds = isFinite(dur) ? Math.ceil(dur) : 0;

        g_DeathActive = true;

        // duration ä¸?0 çš„æƒ…å†µï¼šä»æ˜¾ç¤ºä½†ç”?1 ç§’å…œåº•ï¼Œé¿å…â€œæ˜¾ç¤ºåŽç«‹åˆ»ä¸èµ°â€?
        StartDeathTimer(seconds > 0 ? seconds : 1);
    } else {
        g_DeathActive = false;
        g_DeathRemain = 0;
        row.AddClass("Hidden");
        // ticking é”ä¸å¼ºè¡Œæ”¹ï¼ŒTickDeathTimer ä¸‹ä¸€è½®ä¼šè‡ªåŠ¨é‡Šæ”¾
    }
}

(function () {

    GameEvents.Subscribe("hero_fake_death", OnHeroFakeDeath);

    // ç›‘å¬ wave_info/state
    CustomNetTables.SubscribeNetTableListener("wave_info", (table, key, data) => {
        if (key === "state") {
            WaveState = data;

            // ç¬¬ä¸€æ¬¡æ”¶åˆ°æ•°æ?â†?æ˜¾ç¤ºæ•´ä¸ª UI
            if (!initialized) {

                $("#TopBarContainer").RemoveClass("Hidden");
                $("#TopBarContainer").AddClass("Visible");

                $("#TopBarContent").RemoveClass("Hidden");
                $("#TopBarContent").AddClass("Visible");

                $("#WaveRow").RemoveClass("Hidden");
                $("#WaveRow").AddClass("Visible");

                initialized = true;
            }
        }
    });


    function Update() {
        if (WaveState) {

            const now = Game.GetGameTime();

            /* ç¬¬ä¸€è¡Œï¼šNext / Alive / Boss */
            const nextRemain = Math.max(WaveState.next_wave_time - now, 0);
            $("#NextLabel").text = $.Localize("#Next") + Math.ceil(nextRemain) + "s";

            const alive = WaveState.alive || 0;
            $("#AliveLabel").text = $.Localize("#Alive");

            // ------- è¿›åº¦æ¡æ›´æ–?---------
            const maxAlive = 80;
            let pct = alive / maxAlive;
            if (pct < 0) pct = 0;
            if (pct > 1) pct = 1;

            const bar = $("#AliveBarFill");
            bar.style.width = (pct * 100) + "%";

            let color = "#FFFFFF";      // å®‰å…¨ï¼šç™½è‰?

            if (pct >= 0.40 && pct < 0.70) color = "#E7BA01";      // é»„è‰²
            else if (pct >= 0.70 && pct < 0.85) color = "#FF7F00"; // æ©™è‰²
            else if (pct >= 0.85 && pct <= 1.00) color = "#FF3F3F"; // çº¢è‰²
            else if (pct > 1.0) color = "#A60000";                 // æ·±çº¢ï¼ˆè¶…è¿‡ä¸Šé™ï¼‰

            bar.style.backgroundColor = color;
            $("#AliveBarText").text = alive + " / " + maxAlive;

            const bossRemain = Math.max(WaveState.next_boss_time - now, 0);
